Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -39,4 +39,42 @@
     <div class="touch-controls"><div class="joystick" id="joystick"><div class="joy-knob" id="joyKnob"></div></div><div><button class="cast-btn" id="castBtn" aria-label="Cast spell">✧</button><div class="cast-caption">CAST</div></div></div>
   </footer>
 </main>
 <script>
+(() => {
+  const canvas = document.getElementById('game'), ctx = canvas.getContext('2d');
+  const stage = document.getElementById('stage');
+  const $ = id => document.getElementById(id);
+  const spells = [
+    {name:'Ember bolt',desc:'A seeking flame',unlock:1,color:'#ffbb71',damage:22,rate:.48,speed:370,size:7,count:1},
+    {name:'Moon shard',desc:'Piercing lunar glass',unlock:2,color:'#9bd8f1',damage:17,rate:.62,speed:440,size:6,count:2,pierce:1},
+    {name:'Briar ring',desc:'Thorns bloom around you',unlock:4,color:'#a7e58a',damage:24,rate:.85,speed:270,size:8,count:3},
+    {name:'Starfall',desc:'A little cosmic ruin',unlock:6,color:'#e2a8ff',damage:48,rate:1.05,speed:320,size:10,count:1,pierce:2}
+  ];
+  const keys = new Set(); let W=960,H=600,dpr=1,last=0,elapsed=0,spawnTimer=1.5,castTimer=0,damageTimer=0,shake=0;
+  let running=false,paused=false,selected=0,joy={x:0,y:0},casting=false,messageTimer=0;
+  let player,enemies=[],shots=[],particles=[],decor=[],score=0,kills=0,wave=1,night=1,spawned=0;
+  const rand=(a,b)=>a+Math.random()*(b-a), clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
+  function resize(){const r=stage.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);makeDecor()}
+  function makeDecor(){decor=[];for(let i=0;i<Math.floor(W*H/3900);i++){decor.push({x:rand(12,W-12),y:rand(12,H-12),r:rand(2,7),type:Math.random()})}}
+  function reset(){player={x:W/2,y:H/2,hp:100,maxHp:100,level:1,xp:0,next:30,face:1};enemies=[];shots=[];particles=[];kills=0;score=0;wave=1;night=1;spawned=0;elapsed=0;spawnTimer=.9;castTimer=0;damageTimer=0;selected=0;paused=false;running=true;updateHud();selectSpell(0);}
+  function updateHud(){ $('hpText').textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;$('hpBar').style.width=`${100*player.hp/player.maxHp}%`;$('levelText').textContent=player.level;$('xpText').textContent=`${player.xp} / ${player.next}`;$('xpBar').style.width=`${100*player.xp/player.next}%`;$('waveText').textContent=wave;$('nightText').textContent=['I','II','III','IV','V','VI'][Math.min(5,night-1)]; }
+  function selectSpell(i){if(!spells[i]||player&&spells[i].unlock>player.level)return;selected=i;document.querySelectorAll('.spell').forEach((el,n)=>el.classList.toggle('active',n===i));$('spellTitle').textContent=spells[i].name;$('spellDesc').textContent=spells[i].desc;$('castBtn').textContent=['✧','☾','❋','✹'][i]}
+  function toast(text){const el=$('message');el.textContent=text;el.classList.add('show');messageTimer=2.2}
+  function spawnEnemy(){const edge=Math.floor(Math.random()*4),pad=32;let x=edge===0?-pad:edge===1?W+pad:rand(0,W),y=edge===2?-pad:edge===3?H+pad:rand(0,H);const type= Math.random() < Math.min(.25,.08+night*.025)?'brute':Math.random()<.30?'wisp':'mossling';let e={x,y,type,r:type==='brute'?19:type==='wisp'?11:14,hp:type==='brute'?74:type==='wisp'?24:38,max:type==='brute'?74:type==='wisp'?24:38,speed:type==='brute'?30:type==='wisp'?57:43,damage:type==='brute'?18:10,value:type==='brute'?18:type==='wisp'?9:10,hit:0,phase:rand(0,6.28)};e.hp+=Math.max(0,night-1)*7;e.max=e.hp;enemies.push(e);spawned++}
+  function addParticles(x,y,color,n=8,power=90){for(let i=0;i<n;i++){let a=rand(0,Math.PI*2),v=rand(power*.25,power);particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:rand(.25,.7),max:.7,color,r:rand(1.5,4)})}}
+  function cast(){if(!running||paused||!player)return;const sp=spells[selected];if(castTimer>0)return;castTimer=sp.rate;let target=null,dist=Infinity;for(const e of enemies){let d=Math.hypot(e.x-player.x,e.y-player.y);if(d<dist){dist=d;target=e}}
+    let angle=target?Math.atan2(target.y-player.y,target.x-player.x):Math.atan2(joy.y||0,joy.x||player.face);if(!target&&Math.abs(joy.x)+Math.abs(joy.y)<.1)angle=player.face>0?0:Math.PI;
+    if(selected===2){for(let i=0;i<sp.count;i++){let a=angle+(i-1)*.48;shots.push({x:player.x+Math.cos(a)*16,y:player.y+Math.sin(a)*16,vx:Math.cos(a)*sp.speed,vy:Math.sin(a)*sp.speed,life:1.25,damage:sp.damage,color:sp.color,r:sp.size,pierce:0,hit:[]})}}
+    else for(let i=0;i<sp.count;i++){let a=angle+(i-(sp.count-1)/2)*.13;shots.push({x:player.x+Math.cos(a)*15,y:player.y+Math.sin(a)*15,vx:Math.cos(a)*sp.speed,vy:Math.sin(a)*sp.speed,life:1.6,damage:sp.damage,color:sp.color,r:sp.size,pierce:sp.pierce||0,hit:[]})}
+    addParticles(player.x+Math.cos(angle)*15,player.y+Math.sin(angle)*15,sp.color,4,50);
+  }
+  function damageEnemy(e,amount){e.hp-=amount;e.hit=.12;addParticles(e.x,e.y,'#f3d9a0',3,45);if(e.hp<=0){enemies.splice(enemies.indexOf(e),1);kills++;score+=e.value;addParticles(e.x,e.y,e.type==='wisp'?'#9bd8f1':'#a7d987',12,110);player.xp+=e.value;while(player.xp>=player.next){player.xp-=player.next;player.level++;player.next=Math.round(player.next*1.35);player.hp=Math.min(player.maxHp,player.hp+22);toast(`Level ${player.level} — magic deepens`);if(spells.some(s=>s.unlock===player.level))setTimeout(()=>toast(`${spells.find(s=>s.unlock===player.level).name} discovered!`),850);for(let i=0;i<spells.length;i++){document.querySelectorAll('.spell')[i].classList.toggle('locked',spells[i].unlock>player.level)}if(spells[selected].unlock>player.level)selectSpell(spells.findIndex(s=>s.unlock<=player.level));}updateHud()}}
+  function step(dt){if(!running||paused)return;elapsed+=dt;castTimer-=dt;damageTimer-=dt;spawnTimer-=dt;if(messageTimer>0){messageTimer-=dt;if(messageTimer<=0)$('message').classList.remove('show')}
+    const speed=190;let mx=(keys.has('ArrowRight')||keys.has('d')?1:0)-(keys.has('ArrowLeft')||keys.has('a')?1:0)+joy.x,my=(keys.has('ArrowDown')||keys.has('s')?1:0)-(keys.has('ArrowUp')||keys.has('w')?1:0)+joy.y;let mag=Math.hypot(mx,my);if(mag>1){mx/=mag;my/=mag}player.x=clamp(player.x+mx*speed*dt,24,W-24);player.y=clamp(player.y+my*speed*dt,45,H-24);if(mx)player.face=mx>0?1:-1;
+    if((keys.has(' ')||casting)&&castTimer<=0)cast();
+    if(spawnTimer<=0&&enemies.length<Math.min(14,4+night*2)){spawnEnemy();spawnTimer=Math.max(.56,1.35-night*.07-rand(0,.35))}
+    if(spawned>=10+(wave-1)*5&&enemies.length===0){wave++;if(wave%3===0){night++;toast(`Night ${night} descends`)}spawned=0;updateHud()}
+    for(const e of [...enemies]){e.hit=Math.max(0,e.hit-dt);e.phase+=dt*3;let dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy)||1;e.x+=dx/d*e.speed*dt;e.y+=dy/d*e.speed*dt;if(d<e.r+14&&damageTimer<=0){player.hp-=e.damage;damageTimer=.8;shake=8;addParticles(player.x,player.y,'#ff8b76',9,90);updateHud();if(player.hp<=0){player.hp=0;endGame()}}}
+    for(const s of [...shots]){s.life-=dt;s.x+=s.vx*dt;s.y+=s.vy*dt;for(const e of [...enemies])if(!s.hit.includes(e)&&Math.hypot(e.x-s.x,e.y-s.y)<e.r+s.r){s.hit.push(e);damageEnemy(e,s.damage);if(s.pierce>0)s.pierce--;else{s.life=0;break}}if(s.life<=0||s.x<-30||s.y<-30||s.x>W+30||s.y>H+30)shots.splice(shots.indexOf(s),1)}
+    for(const p of [...particles]){p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.96;p.vy*=.96;if(p.life<=0)particles.splice(particles.indexOf(p),1)}if(shake>0)shake=Math.max(0,shake-dt*22);
+  }

input.newString:
    for(const p of [...particles]){p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.96;p.vy*=.96;if(p.life<=0)particles.splice(particles.indexOf(p),1)}if(shake>0)shake=Math.max(0,shake-dt*22);
  }
  function ellipse(x,y,rx,ry,color){ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}
  function drawGround(){
    const bg=ctx.createLinearGradient(0,0,W,H);bg.addColorStop(0,'#314536');bg.addColorStop(.5,'#263d32');bg.addColorStop(1,'#1c302c');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
    // soft forest-floor patches and old mossy stepping stones
    for(let i=0;i<decor.length;i++){const d=decor[i];if(d.type<.32){ellipse(d.x,d.y,d.r*2.7,d.r*1.35,'#9b9b5730')}else if(d.type<.52){ellipse(d.x,d.y,d.r*1.3,d.r*.8,'#0d211d66');ellipse(d.x-1,d.y-2,d.r,d.r*.6,'#71875b35')}else if(d.type<.7){ctx.strokeStyle='#c1bd8150';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(d.x-4,d.y+3);ctx.lineTo(d.x,d.y-4);ctx.lineTo(d.x+5,d.y+2);ctx.stroke()}else{ellipse(d.x,d.y,d.r*.55,d.r*.55,d.type<.85?'#dca2a059':'#d7c68066');ellipse(d.x,d.y,d.r*.2,d.r*.2,'#efe5ac99')}}
    // winding, pale trail through the clearing
    ctx.save();ctx.globalAlpha=.16;ctx.strokeStyle='#d2c49a';ctx.lineWidth=Math.min(W,H)*.17;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(W*.05,H*.83);ctx.bezierCurveTo(W*.34,H*.66,W*.30,H*.38,W*.64,H*.42);ctx.bezierCurveTo(W*.82,H*.47,W*.82,H*.22,W*1.05,H*.17);ctx.stroke();ctx.restore();
    // dark, leafy border gives the clearing a sense of place
    const edge=ctx.createLinearGradient(0,0,0,H);edge.addColorStop(0,'#0d1b1b8c');edge.addColorStop(.1,'#0d1b1b00');edge.addColorStop(.86,'#0d1b1b00');edge.addColorStop(1,'#0d1b1bb0');ctx.fillStyle=edge;ctx.fillRect(0,0,W,H);
    for(let i=0;i<Math.floor(W/95)+2;i++){let x=i*102-35; if(i%2===0){ellipse(x,8,rand(24,38),22,'#14231fc4');ellipse(x+13,5,21,17,'#24392c');ellipse(x+7,16,5,3,'#85945e66')}else{ellipse(x,H-5,34,22,'#13221ec7');ellipse(x+8,H-13,22,16,'#263a2d')}}
  }
  function drawPlayer(){const p=player,t=elapsed;ellipse(p.x,p.y+11,17,7,'#0915137a');
    // cloak
    ctx.fillStyle='#69547d';ctx.beginPath();ctx.moveTo(p.x-12,p.y-4);ctx.quadraticCurveTo(p.x-19,p.y+18,p.x,p.y+21);ctx.quadraticCurveTo(p.x+18,p.y+16,p.x+11,p.y-5);ctx.closePath();ctx.fill();ctx.fillStyle='#9276a0';ctx.beginPath();ctx.moveTo(p.x-9,p.y+8);ctx.quadraticCurveTo(p.x,p.y+13,p.x+10,p.y+7);ctx.lineTo(p.x+5,p.y+17);ctx.quadraticCurveTo(p.x,p.y+20,p.x-7,p.y+15);ctx.fill();
    // face and hair
    ellipse(p.x,p.y-5,8,9,'#f0c39b');ctx.fillStyle='#422e42';ctx.beginPath();ctx.arc(p.x,p.y-8,8,Math.PI,0);ctx.lineTo(p.x+7,p.y-3);ctx.quadraticCurveTo(p.x,p.y-7,p.x-7,p.y-3);ctx.fill();ellipse(p.x+3,p.y-5,1.2,1.2,'#433547');
    // iconic witch hat
    ctx.fillStyle='#292735';ctx.beginPath();ctx.moveTo(p.x-14,p.y-10);ctx.lineTo(p.x+1,p.y-29);ctx.lineTo(p.x+11,p.y-10);ctx.closePath();ctx.fill();ellipse(p.x-1,p.y-10,15,3.5,'#3c3446');ctx.strokeStyle='#e3bd72';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(p.x-5,p.y-19);ctx.lineTo(p.x+4,p.y-17);ctx.stroke();
    // staff, glowing tip
    ctx.strokeStyle='#ae8358';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(p.x+12,p.y+8);ctx.lineTo(p.x+18,p.y-12);ctx.stroke();ellipse(p.x+18,p.y-14,3.5,3.5,'#ffc980');ellipse(p.x+18,p.y-14,7,7,'#ffc98026');
    if(damageTimer>.57){ctx.strokeStyle='#ff927a';ctx.lineWidth=2;ctx.beginPath();ctx.arc(p.x,p.y,25,0,Math.PI*2);ctx.stroke()}
  }
  function drawEnemy(e){const bob=Math.sin(e.phase)*2, y=e.y+bob;ellipse(e.x,e.y+e.r*.7,e.r*1.1,e.r*.42,'#07141183');if(e.type==='mossling'){
      ellipse(e.x,e.y,e.r,e.r*.92,e.hit?'#f7dca3':'#788e57');ellipse(e.x-4,y-4,5,6,'#8fa36a');ellipse(e.x+5,y-3,4,5,'#667b4c');ellipse(e.x-4,y,1.7,2,'#172a21');ellipse(e.x+5,y,1.7,2,'#172a21');ctx.strokeStyle='#ddbd82';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(e.x-3,y+6);ctx.quadraticCurveTo(e.x+1,y+9,e.x+5,y+5);ctx.stroke();
    }else if(e.type==='wisp'){
      ellipse(e.x,y,e.r*.75,e.r,'#8cc9c1');ellipse(e.x,y-3,e.r*.52,e.r*.65,e.hit?'#fff':'#b4e6d4');ellipse(e.x-3,y-2,1.5,2,'#334c50');ellipse(e.x+3,y-2,1.5,2,'#334c50');ellipse(e.x,y,20,20,'#9fe7d227');
    }else{
      ellipse(e.x,y,e.r,e.r*.9,e.hit?'#f7dca3':'#806d6b');ellipse(e.x-7,y-4,7,8,'#72615f');ellipse(e.x+7,y-4,7,8,'#72615f');ctx.fillStyle='#c18d74';ctx.beginPath();ctx.moveTo(e.x-13,y-12);ctx.lineTo(e.x-17,y-25);ctx.lineTo(e.x-5,y-16);ctx.moveTo(e.x+10,y-15);ctx.lineTo(e.x+18,y-25);ctx.lineTo(e.x+15,y-9);ctx.fill();ellipse(e.x-5,y,2,2,'#f3bf78');ellipse(e.x+5,y,2,2,'#f3bf78');
    }
    if(e.hp<e.max){ctx.fillStyle='#15211c';ctx.fillRect(e.x-e.r,e.y-e.r-10,e.r*2,3);ctx.fillStyle='#e88470';ctx.fillRect(e.x-e.r,e.y-e.r-10,e.r*2*e.hp/e.max,3)}
  }
  function draw(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);ctx.save();if(shake>0)ctx.translate(rand(-shake,shake),rand(-shake,shake));drawGround();for(const e of enemies)drawEnemy(e);drawPlayer();for(const s of shots){ellipse(s.x,s.y,s.r*1.7,s.r*1.7,s.color+'35');ellipse(s.x,s.y,s.r,s.r,s.color);ellipse(s.x-s.r*.25,s.y-s.r*.3,s.r*.32,s.r*.32,'#fff8')}for(const p of particles){ctx.globalAlpha=clamp(p.life/p.max,0,1);ellipse(p.x,p.y,p.r,p.r,p.color)}ctx.globalAlpha=1;ctx.restore();
  }
  function frame(now){const dt=Math.min(.04,(now-last)/1000||0);last=now;if(running&&!paused)step(dt);if(player)draw();requestAnimationFrame(frame)}
  function start(){reset();$('overlay').classList.add('hidden');$('cardEyebrow').textContent='A spellbound adventure';$('cardTitle').textContent='The woods are waking';$('startBtn').textContent='Enter the glade'}
  function endGame(){running=false;$('cardEyebrow').textContent='The glade remembers';$('cardTitle').textContent='Your light fades';$('cardCopy').textContent=`You banished ${kills} creatures and reached level ${player.level}. The woods will be waiting when you return.`;$('startBtn').textContent='Rise again';$('cardHint').textContent='A NEW NIGHT, A NEW CHANCE';$('overlay').classList.remove('hidden')}
  function togglePause(){if(!running)return;paused=!paused;if(paused){$('cardEyebrow').textContent='Take a breath';$('cardTitle').textContent='The glade is still';$('cardCopy').textContent='The shadows can wait. Your spells and progress are safe.';$('startBtn').textContent='Resume';$('cardHint').textContent='PRESS ESC OR TAP RESUME';$('overlay').classList.remove('hidden')}else $('overlay').classList.add('hidden')}
  $('startBtn').addEventListener('click',()=>{if(running&&paused){paused=false;$('overlay').classList.add('hidden')}else start()});$('pauseBtn').addEventListener('click',togglePause);
  document.getElementById('soundBtn').addEventListener('click',e=>{e.currentTarget.textContent=e.currentTarget.textContent==='♪'?'♫':'♪';toast('The woods hum softly')});
  document.querySelectorAll('.spell').forEach(el=>el.addEventListener('click',()=>selectSpell(Number(el.dataset.spell))));
  window.addEventListener('keydown',e=>{const key=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(key))e.preventDefault();if(key==='escape'){togglePause();return}if('1234'.includes(key))selectSpell(Number(key)-1);keys.add(key)});
  window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();casting=false;joy.x=joy.y=0});
  const joystick=$('joystick'),knob=$('joyKnob');let joyPointer=null;
  function moveJoy(e){const r=joystick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),max=r.width*.34,d=Math.hypot(dx,dy),scale=d>max?max/d:1;joy.x=dx*scale/max;joy.y=dy*scale/max;knob.style.left=`${50+joy.x*34}%`;knob.style.top=`${50+joy.y*34}%`}
  joystick.addEventListener('pointerdown',e=>{joyPointer=e.pointerId;joystick.setPointerCapture(joyPointer);moveJoy(e)});joystick.addEventListener('pointermove',e=>{if(e.pointerId===joyPointer)moveJoy(e)});function releaseJoy(){joyPointer=null;joy.x=joy.y=0;knob.style.left='50%';knob.style.top='50%'}joystick.addEventListener('pointerup',releaseJoy);joystick.addEventListener('pointercancel',releaseJoy);
  const castBtn=$('castBtn');castBtn.addEventListener('pointerdown',e=>{e.preventDefault();casting=true;cast()});for(const ev of ['pointerup','pointercancel','pointerleave'])castBtn.addEventListener(ev,()=>casting=false);
  new ResizeObserver(resize).observe(stage);resize();requestAnimationFrame(frame);
})();
</script>
</body>
</html>

